// ── Prompt Hub Data ──────────────────────────────────────────────
// Each collection has a slug, belongs to a category group, and contains
// 5–8 individual ready-to-use prompts.

export interface Prompt {
  id: string;
  title: string;
  prompt: string;
  tags: string[];
}

export interface PromptCollection {
  slug: string;
  title: string;
  description: string;
  emoji: string;
  category: string;          // group heading on the hub page
  promptCount: number;
  prompts: Prompt[];
}

