// ── Helper: get collection by slug ─────────────────────────────
export function getCollectionBySlug(slug: string): PromptCollection | undefined {
  return PROMPT_COLLECTIONS.find((c) => c.slug === slug);
}

// ── Helper: get collections by category ────────────────────────
export function getCollectionsByCategory(categoryId: string): PromptCollection[] {
  return PROMPT_COLLECTIONS.filter((c) => c.category === categoryId);
}
